CREATE TABLE IF NOT EXISTS merchants(id TEXT PRIMARY KEY,name TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS streets(id TEXT PRIMARY KEY,name TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS customers(id TEXT PRIMARY KEY,name TEXT NOT NULL,phone TEXT UNIQUE,street_id TEXT REFERENCES streets(id),opt_in INTEGER NOT NULL DEFAULT 0,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS routes(id TEXT PRIMARY KEY,street_id TEXT REFERENCES streets(id),name TEXT NOT NULL,days TEXT NOT NULL,arrival TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'SCHEDULED',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS products(id TEXT PRIMARY KEY,merchant_id TEXT REFERENCES merchants(id),name TEXT NOT NULL,tamil TEXT NOT NULL,aliases TEXT NOT NULL,category TEXT NOT NULL,unit TEXT NOT NULL CHECK(unit IN ('kg','bunch','100g')),created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS daily_inventory(id TEXT PRIMARY KEY,product_id TEXT REFERENCES products(id),day TEXT NOT NULL,cost INTEGER NOT NULL CHECK(cost>=0),price INTEGER NOT NULL CHECK(price>=0),stock INTEGER NOT NULL CHECK(stock>=0),reserved INTEGER NOT NULL DEFAULT 0 CHECK(reserved>=0 AND reserved<=stock),available INTEGER NOT NULL DEFAULT 1,UNIQUE(product_id,day));
CREATE TABLE IF NOT EXISTS orders(id TEXT PRIMARY KEY,customer_id TEXT REFERENCES customers(id),route_id TEXT REFERENCES routes(id),visit TEXT NOT NULL,status TEXT NOT NULL,total INTEGER NOT NULL DEFAULT 0,handoff TEXT NOT NULL DEFAULT 'At my door',created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS order_items(id TEXT PRIMARY KEY,order_id TEXT REFERENCES orders(id),product_id TEXT REFERENCES products(id),inventory_id TEXT REFERENCES daily_inventory(id),quantity INTEGER NOT NULL CHECK(quantity>0),price INTEGER NOT NULL,amount INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS special_requests(id TEXT PRIMARY KEY,order_id TEXT REFERENCES orders(id),product_id TEXT REFERENCES products(id),quantity INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'PENDING_VENDOR',price INTEGER,minimum INTEGER DEFAULT 0,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS payments(id TEXT PRIMARY KEY,order_id TEXT UNIQUE REFERENCES orders(id),status TEXT NOT NULL DEFAULT 'UNPAID',amount INTEGER NOT NULL,provider TEXT NOT NULL,link_id TEXT,url TEXT,transaction_id TEXT UNIQUE,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS messages(id TEXT PRIMARY KEY,customer_id TEXT REFERENCES customers(id),text TEXT NOT NULL,response TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS vendor_purchase_summaries(id TEXT PRIMARY KEY,day TEXT NOT NULL,content TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS orders_customer ON orders(customer_id,created_at);
CREATE INDEX IF NOT EXISTS items_order ON order_items(order_id);
CREATE INDEX IF NOT EXISTS requests_status ON special_requests(status);
CREATE INDEX IF NOT EXISTS messages_customer ON messages(customer_id);
